-- public.cellar_stack_refusal(p_world uuid, p_level integer, p_x integer, p_y integer)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.cellar_stack_refusal(p_world uuid, p_level integer, p_x integer, p_y integer)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  select case when p_level = 1 then (select upper(left(floor_kind_name(f.kind), 1)) || substr(floor_kind_name(f.kind), 2) || ' down to the cellar is there.' from floor_tile f
                                      where f.world_id = p_world and f.level = 0 and f.x = p_x and f.y = p_y
                                        and f.kind in ('stairs', 'ladder'))
              when p_level = 0 then (select upper(left(floor_kind_name(f.kind), 1)) || substr(floor_kind_name(f.kind), 2) || ' up to the next storey is there.' from floor_tile f
                                      where f.world_id = p_world and f.level = 1 and f.x = p_x and f.y = p_y
                                        and f.kind in ('stairs', 'ladder')) end
$function$
